ls node_modules | grep -E "^(jsdom|happy-dom)$"; mkdir -p /tmp/theme-check && cat > /tmp/theme-check/theme-storage.check.test.ts <<'EOF'
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { loadSavedTheme, saveTheme, THEME_STORAGE_KEY } from '/home/sandbox/workspace/src/theme-storage';

function installWindow(store: Record<string, string> | 'throw') {
  const ls = store === 'throw'
    ? { getItem: () => { throw new Error('denied'); }, setItem: () => { throw new Error('denied'); } }
    : {
        getItem: (k: string) => (k in store ? store[k] : null),
        setItem: (k: string, v: string) => { store[k] = v; },
      };
  (globalThis as any).window = { localStorage: ls };
  return store;
}

describe('theme storage', () => {
  beforeEach(() => { delete (globalThis as any).window; });

  it('defaults to light when nothing is saved', () => {
    installWindow({});
    expect(loadSavedTheme()).toBe('light');
  });

  it('restores each valid saved theme', () => {
    for (const t of ['light', 'dark', 'system']) {
      installWindow({ [THEME_STORAGE_KEY]: t });
      expect(loadSavedTheme()).toBe(t);
    }
  });

  it('ignores invalid stored values', () => {
    for (const bad of ['', 'Dark', 'auto', 'default', 'light-hc', '{"a":1}']) {
      installWindow({ [THEME_STORAGE_KEY]: bad });
      expect(loadSavedTheme()).toBe('light');
    }
  });

  it('falls back to default when storage throws', () => {
    installWindow('throw');
    expect(loadSavedTheme()).toBe('light');
    expect(() => saveTheme('dark')).not.toThrow();
  });

  it('saves the theme under the key and round-trips', () => {
    const store = installWindow({});
    saveTheme('dark');
    expect(store[THEME_STORAGE_KEY]).toBe('dark');
    expect(loadSavedTheme()).toBe('dark');
  });
});
EOF
cp /tmp/theme-check/theme-storage.check.test.ts src/__theme_check.test.ts && npx vitest run src/__theme_check.test.ts 2>&1 | tail -25; rm -f src/__theme_check.test.ts; rm -rf /tmp/theme-check; ls src
